function calculatePayback() {
  const totalCost = parseFloat(document.getElementById('totalCost').value) || 0;
  const subsidyAmount = parseFloat(document.getElementById('subsidyAmount').value) || 0;
  const annualElecBill = parseFloat(document.getElementById('annualElecBill').value) || 0;
  const savingRate = parseFloat(document.getElementById('savingRate').value) || 0.22;

  const netCost = Math.max(0, totalCost - subsidyAmount);
  const annualSaving = Math.round(annualElecBill * savingRate);
  const paybackYears = annualSaving > 0 ? (netCost / annualSaving).toFixed(1) : '∞';
  const tenYearsBenefit = Math.round((annualSaving * 10) - netCost);

  const resultBox = document.getElementById('calcResult');
  resultBox.innerHTML = `
    <div class="result-headline">
      結論：実質自己負担は <strong>${netCost.toLocaleString()}円</strong>！ 約<strong>${paybackYears}年</strong> で元が取れます
    </div>
    <div class="metrics-row">
      <div class="metric-card">
        <span>年間削減額</span>
        <strong>${annualSaving.toLocaleString()} 円/年</strong>
        <small>毎月の電気代が約${Math.round(annualSaving / 12).toLocaleString()}円安くなる試算</small>
      </div>
      <div class="metric-card">
        <span>実質負担額</span>
        <strong>${netCost.toLocaleString()} 円</strong>
        <small>総費用から補助金を差し引いた額</small>
      </div>
      <div class="metric-card">
        <span>10年後の累計収支</span>
        <strong style="color: ${tenYearsBenefit >= 0 ? '#10b981' : '#ef4444'}">${tenYearsBenefit >= 0 ? '+' : ''}${tenYearsBenefit.toLocaleString()} 円</strong>
        <small>${tenYearsBenefit >= 0 ? '10年間で完全にプラスへ転換' : '10年超で回収見込み'}</small>
      </div>
    </div>
  `;
}

document.addEventListener('DOMContentLoaded', calculatePayback);
